#!/bin/bash

# Create basic placeholder icons using base64 encoded PNG data
# These are simple solid color icons that will work until better ones are created

cd icons

# 16x16 icon (purple gradient square)
echo "" | base64 -d > icon16.png

# 48x48 icon
echo "" | base64 -d > icon48.png

# 128x128 icon
echo "" | base64 -d > icon128.png

echo "Basic icon files created in icons/"
echo "Note: These are placeholder icons. For better quality, use create-icons.html or generate-icons.py"
